function burst(x,y,color,count=8){for(let i=0;i<count;i++)particles.push({x,y,vx:(Math.random()-.5)*140,vy:-30-Math.random()*130,life:.35+Math.random()*.5,color,size:2+Math.random()*3})}
function update(dt){elapsed+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}
if(screen!=='playing')return;
const h=hero;const accel=keys.left?-1:keys.right?1:0;if(accel)h.face=accel;h.vx+=accel*1050*dt;if(!accel)h.vx*=Math.pow(.001,dt);h.vx=Math.max(-225,Math.min(225,h.vx));if(keys.jump&&!wasJump&&h.onGround){h.vy=-470;h.onGround=false;burst(h.x+h.w/2,h.y+h.h,'#d7c38c',4)}wasJump=keys.jump;
if(keys.attack&&!wasAttack&&h.attackCd<=0){h.attack=.24;h.attackCd=.34}wasAttack=keys.attack;if(h.attack>0)h.attack=Math.max(0,h.attack-dt);if(h.attackCd>0)h.attackCd-=dt;if(h.invuln>0)h.invuln-=dt;
h.vy=Math.min(800,h.vy+1250*dt);const oldBottom=h.y+h.h;h.x=Math.max(0,Math.min(world.width-h.w,h.x+h.vx*dt));h.y+=h.vy*dt;h.onGround=false;
for(const p of platforms){if(h.x+h.w>p.x&&h.x<p.x+p.w&&oldBottom<=p.y+4&&h.y+h.h>=p.y&&h.vy>=0){h.y=p.y-h.h;h.vy=0;h.onGround=true}}
if(h.y>800){hurt(true)}
for(const c of coins){if(!c.taken&&Math.abs((h.x+h.w/2)-c.x)<21&&Math.abs((h.y+h.h/2)-c.y)<25){c.taken=true;burst(c.x,c.y,'#ffd36f',10);updateHUD();showToast('A little treasure for the road') }}
for(const cp of checkpoints){if(!cp.active&&h.x>cp.x-10&&h.x<cp.x+42){cp.active=true;h.checkpoint=cp.x;showToast('Campfire found · progress saved');burst(cp.x,cp.y-30,'#ffd47d',12)}}
for(const e of enemies){if(!e.alive)continue;e.y=platforms.find(p=>e.home>=p.x&&e.home<p.x+p.w)?.y||460;e.y-=0;e.x+=Math.sign((h.x-e.x)||1)*Math.min(26*dt,Math.abs(h.x-e.x)*.12*dt);e.x=Math.max(e.home-80,Math.min(e.home+80,e.x));
const near=Math.abs((h.x+h.w/2)-e.x)<30&&Math.abs((h.y+h.h)-e.y)<40;if(h.attack>0&&near){e.hp--;e.x+=h.face*18;burst(e.x,e.y-16,'#a8da8e',7);h.attack=0;if(e.hp<=0){e.alive=false;burst(e.x,e.y-15,'#8bd17d',14);showToast('Forest slime defeated')}}else if(near&&h.invuln<=0)hurt(false)}
for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=250*dt;p.life-=dt}particles=particles.filter(p=>p.life>0);
const target=Math.max(0,Math.min(world.width-W/scale,h.x+h.w/2-W/(scale*2)));camX+=(target-camX)*Math.min(1,dt*4.5);
if(h.x>gate.x-26){screen='win';ui.eyebrow.textContent='THE FIRST CHAPTER';ui.title.textContent='The path is open';ui.message.textContent=`You found the old forest gate with ${coins.filter(c=>c.taken).length} of ${coins.length} ember coins. Beyond it, the ruins are calling.`;ui.start.textContent='PLAY AGAIN';ui.hint.textContent='A new adventure waits beyond the gate';ui.overlay.classList.remove('hidden')}
